"""Builds the VS Code extension's generated files from src/ddgbasic.py.

    vscode/syntaxes/ddgbasic.tmLanguage.json   the syntax-highlighting grammar
    vscode/help.json                           the hover help (HelpRegistry.TOPICS)

The keyword lists come from the interpreter itself: the lexer's keywords, the words the
parser matches by name, the HELP topics, the built-in functions and the SQL reserved words.
Run it after adding a statement, a built-in function or a HELP topic:

    python3 tools/gen_vscode.py           # write the files
    python3 tools/gen_vscode.py --check   # exit status 1 if they are out of date
"""
import inspect
import json
import os
import re
import sys

ROOT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
sys.path.insert(0, os.path.join(ROOT, 'src'))
CHECK = '--check' in sys.argv[1:]
sys.argv = ['ddgbasic']
import ddgbasic  # noqa: E402

source = inspect.getsource(ddgbasic)

# --- Words -----------------------------------------------------------------------------
functions = set(ddgbasic.Interpreter.BUILTIN_FN_NAMES)

keywords = set()
# Lexer keywords: ('PRINT', r'\bPRINT\b(?!\$)')
keywords |= set(re.findall(r"\('([A-Z]+)', r'\\b\1\\b", source))
# Words the parser matches by name: tok[1].upper() == 'ROW', ... in ('TRANSFORM', 'VALIDATE')
for group in re.findall(r"\[1\]\.upper\(\) (?:==|in|not in) (\([^)]*\)|\{[^}]*\}|\[[^\]]*\]|'[A-Z_]+')", source):
    keywords |= set(re.findall(r"'([A-Z_]{2,})'", group))
# Form clauses matched with keyword('SAY')
keywords |= set(re.findall(r"\bkeyword\('([A-Z_]+)'\)", source))
# HELP topics: LOAD CSV, SET OUTPUT, ...
for topic in ddgbasic.HelpRegistry.TOPICS:
    keywords |= {w for w in topic.split() if re.fullmatch(r'[A-Z_]+', w)}
# The lexer joins these from two words (END IF -> ENDIF); highlight the parts
keywords |= {'END', 'IF', 'ON', 'ERROR', 'GOTO', 'LINE', 'INPUT', 'TRANSACTION', 'EACH'}
# Not statements: the lexer's comment and operator tokens
keywords -= {'REM', 'AND', 'OR', 'NOT', 'MOD', 'TABLE_NAME'}
keywords -= functions

# Words that are keywords only in some statements and ordinary variable or column names
# elsewhere (FOR row IN ..., name$, row.email). They are colored as keywords only at the
# start of a statement or in one of the phrases below, never on their own.
NAME_LIKE = {'NAME', 'TEXT', 'EMAIL', 'ROW', 'HEADERS', 'REPORT', 'SCHEMA', 'SQL', 'KEY',
             'FILE', 'LIST', 'MESSAGE', 'LINE', 'DETAIL', 'VIEW', 'EDIT', 'READ', 'FORMAT',
             'STYLE', 'THEME', 'ALL', 'SAVE', 'PUT', 'PATCH', 'MOUSE', 'OFF', 'TABLES',
             'INDEXES', 'VARIABLES', 'FIELDS', 'LOOKUP', 'CONFIRM', 'CANCEL', 'BUTTON',
             'CHECKBOX', 'HINT', 'REQUIRED', 'PRESERVE', 'SHADOW', 'DETAILS', 'EACH'} & keywords
PHRASES = {('TRANSFORM', 'ROW'), ('VALIDATE', 'ROW'), ('USING', 'KEY'), ('USING', 'SCHEMA'),
           ('LOAD', 'TEXT'), ('IN', 'TEXT'), ('READ', 'FILE'), ('WITH', 'HEADERS'),
           ('FOR', 'EACH'), ('MAKE', 'FORM'), ('MAKE', 'REPORT')}
for topic in ddgbasic.HelpRegistry.TOPICS:
    parts = topic.split()
    if len(parts) > 1 and any(w in NAME_LIKE for w in parts):
        PHRASES |= {(a, b) for a, b in zip(parts, parts[1:])}
PHRASES = {(a, b) for a, b in PHRASES if a in keywords and b in keywords}
keywords -= NAME_LIKE

sql_words = set(ddgbasic.Interpreter.SQL_RESERVED_WORDS) - keywords - functions
sql_words |= {'FROM', 'WHERE', 'JOIN', 'LEFT', 'RIGHT', 'INNER', 'OUTER', 'ON', 'GROUP', 'BY',
              'ORDER', 'HAVING', 'LIMIT', 'OFFSET', 'VALUES', 'DISTINCT', 'PRIMARY', 'KEY',
              'REFERENCES', 'NULL', 'IS', 'LIKE', 'BETWEEN', 'UNION', 'CASE', 'WHEN', 'THEN',
              'ELSE', 'END', 'DESC', 'ASC', 'INDEX', 'VIEW', 'TRIGGER', 'DEFAULT', 'UNIQUE', 'CHECK',
              'INTEGER', 'TEXT', 'REAL', 'NUMERIC', 'BLOB', 'VARCHAR', 'DATE', 'COUNT', 'SUM',
              'AVG', 'COALESCE'}
sql_words -= keywords | functions


def alternation(words):
    # Longest first, so READFILE wins over READ; $ is escaped for the regex
    return '|'.join(re.escape(w) for w in sorted(words, key=lambda w: (-len(w), w)))


def word_pattern(words, dollar):
    # BASIC words never take a $ (PRINT$ is a variable); function names may end in $
    tail = '' if dollar else r'(?!\$)'
    return r'(?i)(?<![\w$])(?:' + alternation(words) + r')' + tail + r'(?![\w$])'


plain_fns = {f for f in functions if not f.endswith('$')}
dollar_fns = {f for f in functions if f.endswith('$')}

grammar = {
    '$schema': 'https://raw.githubusercontent.com/martinring/tmlanguage/master/tmlanguage.json',
    'name': 'DDGBasic',
    'scopeName': 'source.ddgbasic',
    'comment': 'Generated by tools/gen_vscode.py from src/ddgbasic.py. Do not edit by hand.',
    'patterns': [
        {'include': '#comments'},
        {'include': '#strings'},
        {'include': '#label'},
        {'include': '#numbers'},
        {'include': '#functions'},
        {'include': '#phrases'},
        {'include': '#statement-words'},
        {'include': '#keywords'},
        {'include': '#operators'},
        {'include': '#sql'},
        {'include': '#bind'},
        {'include': '#variables'},
    ],
    'repository': {
        'comments': {'patterns': [
            {'name': 'comment.line.rem.ddgbasic', 'match': r'(?i)(?<![\w$])REM(?![\w$]).*$'},
            {'name': 'comment.line.double-dash.ddgbasic', 'match': r'--.*$'},
            {'name': 'comment.block.ddgbasic', 'begin': r'/\*', 'end': r'\*/'},
        ]},
        'strings': {'patterns': [
            {'name': 'string.quoted.double.ddgbasic', 'begin': '"', 'end': '"(?!")',
             'patterns': [{'name': 'constant.character.escape.ddgbasic', 'match': '""'}]},
            {'name': 'string.quoted.single.sql.ddgbasic', 'match': "'[^'\\n]*'"},
            {'name': 'string.interpolated.ddgbasic', 'begin': '`', 'end': '`',
             'patterns': [{'name': 'meta.interpolation.ddgbasic', 'begin': r'\$\{', 'end': r'\}',
                           'beginCaptures': {'0': {'name': 'punctuation.section.interpolation.begin.ddgbasic'}},
                           'endCaptures': {'0': {'name': 'punctuation.section.interpolation.end.ddgbasic'}},
                           'patterns': [{'include': '$self'}]}]},
        ]},
        'label': {'match': r'^\s*([A-Za-z_][A-Za-z0-9_]*)(:)(?!=)\s*(?=$|REM\b|--)',
                  'captures': {'1': {'name': 'entity.name.label.ddgbasic'},
                               '2': {'name': 'punctuation.separator.label.ddgbasic'}}},
        'numbers': {'name': 'constant.numeric.ddgbasic',
                    'match': r'(?<![\w$.])(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?(?![\w$])'},
        'functions': {'patterns': [
            {'name': 'support.function.builtin.ddgbasic', 'match': word_pattern(dollar_fns, True)},
            {'name': 'support.function.builtin.ddgbasic', 'match': word_pattern(plain_fns, False) + r'(?=\s*\()'},
        ]},
        'phrases': {'patterns': [
            {'match': r'(?i)(?<![\w$])(' + re.escape(first) + r')\s+(' + re.escape(second) + r')(?![\w$])',
             'captures': {'1': {'name': 'keyword.control.ddgbasic'}, '2': {'name': 'keyword.control.ddgbasic'}}}
            for first, second in sorted(PHRASES)]},
        # NAME old AS new, REPORT ..., LINE INPUT: at the start of a statement, not assigned to
        'statement-words': {'match': r'(?i)(?:^|(?<=:))\s*(' + alternation(NAME_LIKE) + r')(?![\w$])(?!\s*(?:=|\.|\(|\[))',
                            'captures': {'1': {'name': 'keyword.control.ddgbasic'}}},
        'keywords': {'patterns': [
            {'name': 'keyword.operator.word.ddgbasic', 'match': r'(?i)(?<![\w$])(?:AND|OR|NOT|MOD)(?![\w$])'},
            {'name': 'keyword.control.ddgbasic', 'match': word_pattern(keywords, False)},
        ]},
        'operators': {'name': 'keyword.operator.ddgbasic', 'match': r'<>|<=|>=|[=<>+\-*/^&]'},
        'sql': {'name': 'keyword.other.sql.ddgbasic', 'match': word_pattern(sql_words, False)},
        'bind': {'name': 'variable.parameter.bind.ddgbasic', 'match': r'(?<![\w:]):[A-Za-z_][A-Za-z0-9_]*'},
        'variables': {'name': 'variable.other.ddgbasic', 'match': r'(?<![\w$])[A-Za-z_][A-Za-z0-9_]*\$?'},
    },
}

help_topics = {topic: {'syntax': info.get('syntax', ''), 'desc': info.get('desc', ''),
                       'examples': list(info.get('examples', []))}
               for topic, info in sorted(ddgbasic.HelpRegistry.TOPICS.items())}

# --- Write or check ---------------------------------------------------------------------
outputs = {
    os.path.join(ROOT, 'vscode', 'syntaxes', 'ddgbasic.tmLanguage.json'): grammar,
    os.path.join(ROOT, 'vscode', 'help.json'): help_topics,
}
stale = []
for path, data in outputs.items():
    text = json.dumps(data, indent=2, ensure_ascii=False) + '\n'
    try:
        with open(path, encoding='utf-8', newline='') as f:
            current = f.read()
    except FileNotFoundError:
        current = None
    if current == text:
        continue
    if CHECK:
        stale.append(os.path.relpath(path, ROOT))
    else:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'w', encoding='utf-8', newline='') as f:
            f.write(text)
        print('wrote', os.path.relpath(path, ROOT))
if stale:
    print('Out of date (run python3 tools/gen_vscode.py):', ', '.join(stale), file=sys.stderr)
    sys.exit(1)
